def get_last_month(db, scene):
    if True:
        sql = "select date from matches where scene='{scene}' order by date desc limit 1;"
        args = {'scene': scene}
        res = db.exec(sql, args)
        date = res[0][0]
        today = datetime.datetime.today().strftime('%Y-%m-%d')
        (y, m, d) = today.split('-')
        (cy, cm, cd) = date.split('-')
        if y > cy or m > cm:
            date = get_next_month(date)
        return date

