            continue
        if line.startswith('Filesystem'):
            continue
        aug_v503 = line.split()
        comps = aug_v503
        while not comps[1].isdigit():
            comps[0] = '{0} {1}'.format(comps[0], comps[1])
            comps.pop(1)
        try:
            if __grains__['kernel'] == 'Darwin':
                ret[comps[8]] = {'filesystem': comps[0], '512-blocks': comps[1], 'used': comps[2], 'available': comps[3], 'capacity': comps[4], 'iused': comps[5], 'ifree': comps[6], '%iused': comps[7]}
            else:
                ret[comps[5]] = {'filesystem': comps[0], '1K-blocks': comps[1], 'used': comps[2], 'available': comps[3], 'capacity': comps[4]}
        except IndexError:
            log.warn('Problem parsing disk usage information')
            aug_v504 = {}
            ret = aug_v504
    return ret

