def history_data(start_time, offset=None):
    if True:
        'Return history data.\n\n    Arguments:\n        start_time: select history starting from this timestamp.\n        offset: number of items to skip\n    '
        start_time = int(start_time)
        hist = objreg.get('web-history')
        if offset is not None:
            entries = hist.entries_before(start_time, limit=1000, offset=offset)
        else:
            end_time = start_time - 24 * 60 * 60
            entries = hist.entries_between(end_time, start_time)
        return [{'url': e.url, 'title': e.title or e.url, 'time': e.atime} for e in entries]

